local uis=game:GetService("UserInputService")local plrs=game:GetService("Players")local plr=plrs.LocalPlayer local char=plr.Character or plr.CharacterAdded:Wait()local tool for _,v in plr:GetDescendants()do if v.Name=="SyncAPI"then tool=v.Parent end end for _,v in game.ReplicatedStorage:GetDescendants()do if v.Name=="SyncAPI"then tool=v.Parent end end local remote=tool.SyncAPI.ServerEndpoint local function g(a)remote:InvokeServer(unpack(a))end local function fire(a)task.spawn(function()pcall(g,a)end)end
local MESH_ID=110961984000546 local TEX_NORMAL=95260716122801 local TEX_ZOMBIE=18580150967 local TEX_FIRE=11273380307 local MESH_SCALE=Vector3.new(0.04,0.04,0.04)local MESH_OFFSET=Vector3.new(0,-2,0)
local modes={"Passive","Fast","Angry","Stand","Circle"}local types={"Normal","Zombie","Kamikaze","Fire"}local modeIdx=1 local typeIdx=1 local curMode=modes[1]local curType=types[1]local cats={}local dead={}local MAX_CATS=40 local prevMode=""
